from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3

    def test_add_and_get(self, repo):
        task = Task(id=1, title="Test")
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_id_raises(self, repo):
        task = Task(id=1, title="Test")
        repo.add(task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(Task(id=1, title="Dup"))

    def test_list_returns_all(self, repo):
        repo.add(Task(id=1, title="A"))
        repo.add(Task(id=2, title="B"))
        items = list(repo.list())
        assert len(items) == 2

    def test_update_existing(self, repo):
        task = Task(id=1, title="Original")
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(Task(id=99, title="X"))

    def test_delete_existing_returns_true(self, repo):
        repo.add(Task(id=1, title="X"))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_deduplicates_by_normalized_name(self):
        result = normalize_tags(["Foo", "FOO", "foo"])
        assert len(result) == 1
        assert result[0].name == "foo"

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["beta", "alpha", "gamma"])
        assert [t.name for t in result] == ["beta", "alpha", "gamma"]

    def test_accepts_tag_instances(self):
        result = normalize_tags([Tag("hello"), Tag("hello")])
        assert len(result) == 1

    def test_empty_iterable(self):
        result = normalize_tags([])
        assert result == []

    def test_mixed_strings_and_tags(self):
        result = normalize_tags(["foo", Tag("bar"), "FOO"])
        assert len(result) == 2
        assert [t.name for t in result] == ["foo", "bar"]

