class TestNormalizeTags:
    def test_deduplicates_by_normalized_name(self):
        result = normalize_tags(["Foo", "FOO", "foo"])
        assert len(result) == 1
        assert result[0].name == "foo"

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["beta", "alpha", "gamma"])
        assert [t.name for t in result] == ["beta", "alpha", "gamma"]

    def test_accepts_tag_instances(self):
        result = normalize_tags([Tag("hello"), Tag("hello")])
        assert len(result) == 1

    def test_empty_iterable(self):
        result = normalize_tags([])
        assert result == []

    def test_mixed_strings_and_tags(self):
        result = normalize_tags(["foo", Tag("bar"), "FOO"])
        assert len(result) == 2
        assert [t.name for t in result] == ["foo", "bar"]
